// One outstanding animation callback, even when observers fire repeatedly.
export function createFrameLoop(render, request = requestAnimationFrame, cancel = cancelAnimationFrame) {
  let frame = null;
  let running = false;
  let disposed = false;
  let previousTime = null;
  function tick(time) {
    frame = null;
    if (!running || disposed) return;
    const delta = previousTime === null ? 0 : Math.min(Math.max((time - previousTime) / 1000, 0), .05);
    previousTime = time;
    render(delta);
    if (running && !disposed) frame = request(tick);
  }
  function setRunning(next) {
    if (disposed || next === running) return;
    running = next;
    previousTime = null;
    if (running) frame = request(tick);
    else if (frame !== null) { cancel(frame); frame = null; }
  }
  return {
    setRunning,
    dispose() { setRunning(false); disposed = true; },
  };
}
