import { createApp } from 'vue'
import App from './App.vue'

import VTooltip from 'v-tooltip';

// Vuetify
import 'vuetify/styles'
import { createVuetify } from 'vuetify'
import * as components from 'vuetify/components'
import * as directives from 'vuetify/directives'
import '@mdi/font/css/materialdesignicons.css'

// Vue Router
import { createRouter, createWebHashHistory } from 'vue-router'
import HomePage from './views/HomePage.vue'
import SuraDemo from './views/SuraDemo.vue'
import DelaunayTriangulation from './views/DelaunayTriangulation.vue'
import info from './info'

//*import LifeDemo from './views/LifeDemo.vue'
//*import PortfolioPage from './views/PortfolioPage.vue'

const routes = [
  { path: '/', component: HomePage },
  { path: '/sura-demo', component: SuraDemo },
  { path: '/delaunay-triangulation', component: DelaunayTriangulation },
  { path: '/3d-artwork', component: HomePage, meta: { artworkId: 'artwork-3d' } },
  { path: '/2d-artwork', component: HomePage, meta: { artworkId: 'artwork-2d' } },
  ...info.portfolio.map(({ name }) => {
    const slug = name.toLowerCase().replace(/[^a-z0-9]+/g, '-')
    return { path: `/${slug}`, component: HomePage, meta: { projectId: `project-${slug}` } }
  })
  //*{ path: '/portfolio', component: PortfolioPage },
  //*{ path: '/password-safety', component: LifeDemo },
]

const router = createRouter({
  history: createWebHashHistory(),
  routes,
  async scrollBehavior(to, from, savedPosition) {
    if (to.meta.projectId || to.meta.artworkId) {
      // Font loading can shift sections on a direct visit.
      await document.fonts.ready
      if (to.fullPath !== router.currentRoute.value.fullPath) return false
      const target = to.meta.projectId
        ? document.getElementById(to.meta.projectId)?.closest('article')
        : document.getElementById(to.meta.artworkId)?.closest('.artwork-group')
      if (target) {
        return { el: target, top: parseFloat(getComputedStyle(target).scrollMarginTop) || 100 }
      }
    }
    if (savedPosition) return savedPosition
    return to.path === '/' ? { top: 0, left: 0 } : false
  }
})

const vuetify = createVuetify({
  components,
  directives,
  theme: {
    defaultTheme: 'light',
    themes: {
      light: {
        'light-color': '#FFFFFF', // Set your custom color here
      },
      dark: {
        'light-color': '#FFFFFF', // Set your custom color for dark mode
      }
    },
  }
})

createApp(App).use(vuetify).use(VTooltip).use(router).mount('#app')
