// A cursor force + damped springs, rather than a neighbor-based fluid solver.
// Fixed typed arrays and bounded substeps keep the work linear in particle count.
export function createParticleMotion(positions, {
  radius = 150, strength = 2600, spring = 22, damping = 7.5,
  maxDisplacement = 180, afterglow = 2,
} = {}) {
  const home = positions.slice();
  const velocity = new Float32Array(positions.length);
  const glow = new Float32Array(positions.length / 3);
  const glowPeak = new Float32Array(glow.length);
  const glowRemaining = new Float32Array(glow.length);
  let moving = false;
  let glowing = false, glowChanged = false;
  let extentSquared = 0;
  for (let i = 0; i < home.length; i += 3) {
    extentSquared = Math.max(extentSquared, home[i] ** 2 + home[i + 1] ** 2 + home[i + 2] ** 2);
  }
  const influenceSquared = (Math.sqrt(extentSquared) + radius + maxDisplacement) ** 2;
  const radiusSquared = radius * radius;
  const limitSquared = maxDisplacement * maxDisplacement;

  // Hold each particle's highlight while it moves, then fade it after settling.
  // Reuse the physics traversal; once motion stops, only the small glow arrays
  // need updating, and those also go idle after the two-second tail.
  function updateGlow(index, active, displacementSquared, duration) {
    const previous = glow[index];
    if (active) {
      const amount = Math.min(1, Math.sqrt(displacementSquared) / 45);
      glowPeak[index] = Math.max(previous, amount * amount * (3 - 2 * amount));
      glowRemaining[index] = afterglow;
      glow[index] = glowPeak[index];
    } else if (glowRemaining[index] > 0) {
      const remaining = Math.max(0, glowRemaining[index] - duration);
      glowRemaining[index] = remaining;
      const amount = remaining / afterglow;
      glow[index] = glowPeak[index] * amount * amount * (3 - 2 * amount);
    } else {
      glow[index] = 0;
    }
    if (glow[index] !== previous) glowChanged = true;
    if (glow[index] > 0) glowing = true;
  }

  // The ray is expressed in the rotating cube's local space, with a unit direction.
  function step(delta, ray = null) {
    glowChanged = false;
    if (!Number.isFinite(delta) || delta <= 0) return false;
    const duration = Math.min(delta, .05);
    let ox = 0, oy = 0, oz = 0, dx = 0, dy = 0, dz = 0;
    let interact = false;
    if (ray) {
      ({ x: ox, y: oy, z: oz } = ray.origin);
      ({ x: dx, y: dy, z: dz } = ray.direction);
      const along = Math.max(0, -(ox * dx + oy * dy + oz * dz));
      const nearX = ox + along * dx, nearY = oy + along * dy, nearZ = oz + along * dz;
      interact = nearX * nearX + nearY * nearY + nearZ * nearZ < influenceSquared;
    }
    if (!moving && !interact) {
      if (glowing) {
        glowing = false;
        for (let index = 0; index < glow.length; index++) updateGlow(index, false, 0, duration);
      }
      return false;
    }

    glowing = false;
    const substeps = Math.ceil(duration * 120);
    const dt = duration / substeps;
    const drag = Math.exp(-damping * dt);
    let unsettled = false, pushed = false;

    for (let i = 0; i < positions.length; i += 3) {
      const hx = home[i], hy = home[i + 1], hz = home[i + 2];
      let x = positions[i], y = positions[i + 1], z = positions[i + 2];
      let vx = velocity[i], vy = velocity[i + 1], vz = velocity[i + 2];
      for (let substep = 0; substep < substeps; substep++) {
        let fx = -spring * (x - hx), fy = -spring * (y - hy), fz = -spring * (z - hz);
        if (interact) {
          const rx = x - ox, ry = y - oy, rz = z - oz;
          const along = rx * dx + ry * dy + rz * dz;
          let px = rx - along * dx, py = ry - along * dy, pz = rz - along * dz;
          const distanceSquared = px * px + py * py + pz * pz;
          if (along >= 0 && distanceSquared < radiusSquared) {
            const distance = Math.sqrt(distanceSquared);
            if (distance < .0001) {
              // A deterministic perpendicular direction also handles a direct hit.
              if (Math.abs(dz) > .9) { px = -dz; py = 0; pz = dx; }
              else { px = dy; py = -dx; pz = 0; }
              const scale = (i % 2 ? -1 : 1) / Math.hypot(px, py, pz);
              px *= scale; py *= scale; pz *= scale;
            } else {
              px /= distance; py /= distance; pz /= distance;
            }
            const force = strength * (1 - distance / radius) ** 2;
            fx += px * force; fy += py * force; fz += pz * force;
            pushed = true;
          }
        }
        vx = (vx + fx * dt) * drag;
        vy = (vy + fy * dt) * drag;
        vz = (vz + fz * dt) * drag;
        x += vx * dt; y += vy * dt; z += vz * dt;
        const ux = x - hx, uy = y - hy, uz = z - hz;
        const displacementSquared = ux * ux + uy * uy + uz * uz;
        if (displacementSquared > limitSquared) {
          const scale = maxDisplacement / Math.sqrt(displacementSquared);
          x = hx + ux * scale; y = hy + uy * scale; z = hz + uz * scale;
          const outward = Math.max(0, (vx * ux + vy * uy + vz * uz) / displacementSquared);
          vx -= outward * ux; vy -= outward * uy; vz -= outward * uz;
        }
      }
      positions[i] = x; positions[i + 1] = y; positions[i + 2] = z;
      velocity[i] = vx; velocity[i + 1] = vy; velocity[i + 2] = vz;
      const displacementSquared = (x - hx) ** 2 + (y - hy) ** 2 + (z - hz) ** 2;
      const active = displacementSquared > .025 ** 2 || vx * vx + vy * vy + vz * vz > .06 ** 2;
      if (active) unsettled = true;
      updateGlow(i / 3, active, displacementSquared, duration);
    }
    const changed = moving || pushed;
    moving = unsettled || pushed;
    if (!moving) { positions.set(home); velocity.fill(0); }
    return changed;
  }
  return { step, glow, get glowChanged() { return glowChanged; } };
}
