<template>
  <article class="project-card" tabindex="-1" :aria-labelledby="titleId">
    <div class="project-media" :class="{ 'project-media--light': portfolio.mediaTheme === 'light' }" :style="portfolio.mediaAspect ? { aspectRatio: portfolio.mediaAspect } : undefined">
      <video v-if="selectedMedia.video" :key="selectedMedia.video" ref="video" class="project-image" :poster="selectedMedia.src" :src="selectedMedia.video" :aria-label="selectedMedia.alt" :aria-describedby="selectedMedia.caption ? mediaCaptionId : undefined" controls playsinline muted loop preload="none" @pause="onPause"></video>
      <a v-else :href="selectedMedia.original || selectedMedia.src" target="_blank" rel="noopener noreferrer" :aria-label="`Open full-size image: ${selectedMedia.alt}`">
        <img class="project-image" :src="selectedMedia.src" :srcset="imageSrcset" :sizes="imageSizes" :alt="selectedMedia.alt" :aria-describedby="selectedMedia.caption ? mediaCaptionId : undefined" :width="selectedMedia.width" :height="selectedMedia.height" :loading="index < 2 ? 'eager' : 'lazy'" decoding="async" />
      </a>
    </div>
    <div class="image-bar">
      <div v-if="images.length > 1" class="image-options" :aria-label="`${portfolio.name} images`" role="group">
        <button v-for="(item, imageIndex) in images" :key="item.video || item.src" type="button" class="image-option" :aria-pressed="selectedIndex === imageIndex" :aria-label="`Show ${item.video ? 'video' : 'image'} ${imageIndex + 1}: ${item.alt}`" :title="item.caption || item.alt" @click="selectImage(imageIndex)">
          <img :src="item.thumbnail || item.src" alt="" width="44" height="34" loading="lazy" />
          <span v-if="item.video" class="video-badge" aria-hidden="true">▶</span>
        </button>
      </div>
      <span v-else class="media-type">{{ selectedMedia.video ? 'Animation' : 'Project preview' }}</span>
      <a class="full-image" :href="selectedMedia.original || selectedMedia.src" target="_blank" rel="noopener noreferrer">Full size <span class="sr-only">— {{ portfolio.name }}</span><span aria-hidden="true">↗</span></a>
      <p v-if="selectedMedia.caption" :id="mediaCaptionId" class="media-caption" aria-live="polite">{{ selectedMedia.caption }}</p>
    </div>
    <div class="project-copy">
      <p class="project-meta">{{ portfolio.date }}</p>
      <h3 :id="titleId">{{ portfolio.name }}</h3>
      <p v-if="portfolio.role" class="project-role">{{ portfolio.role }}</p>
      <p class="project-summary">{{ portfolio.summary || portfolio.description.split('. ')[0] + '.' }}</p>
      <ul class="project-skills" aria-label="Technologies used"><li v-for="skill in portfolio.skills" :key="skill">{{ skill }}</li></ul>
      <div class="project-actions">
        <button class="read-more" type="button" :aria-expanded="expanded" :aria-controls="detailsId" @click="expanded = !expanded">
          {{ expanded ? 'Read less' : 'Read more' }}<span class="sr-only"> about {{ portfolio.name }}</span><span aria-hidden="true">{{ expanded ? '−' : '+' }}</span>
        </button>
        <div class="project-links">
          <a v-if="portfolio.report" :href="portfolio.report" target="_blank" rel="noopener noreferrer">Project report <span aria-hidden="true">↗</span></a>
          <a v-if="portfolio.github" :href="portfolio.github" target="_blank" rel="noopener noreferrer">GitHub <span aria-hidden="true">↗</span></a>
          <a v-if="portfolio.youtube" :href="portfolio.youtube" target="_blank" rel="noopener noreferrer">Demo video <span aria-hidden="true">↗</span></a>
          <router-link v-if="portfolio.demo" :to="portfolio.demo">Try demo <span aria-hidden="true">↗</span></router-link>
          <a v-if="portfolio.contact" :href="`mailto:${portfolio.contact}?subject=${encodeURIComponent('Code request: ' + portfolio.name)}`">Request code <span aria-hidden="true">↗</span></a>
        </div>
      </div>
      <div v-show="expanded" :id="detailsId" class="project-details"><p>{{ portfolio.description }}</p></div>
    </div>
  </article>
</template>

<script>
export default {
  name: 'CardItem',
  props: {
    portfolio: { type: Object, required: true },
    index: { type: Number, default: 0 },
    media: { type: Array, default: () => [] },
  },
  data() { return { expanded: false, selectedIndex: 0, inView: false, reducedMotion: false, autoplayDisabled: false }; },
  computed: {
    titleId() { return `project-${this.portfolio.name.toLowerCase().replace(/[^a-z0-9]+/g, '-')}`; },
    detailsId() { return `${this.titleId}-details`; },
    mediaCaptionId() { return `${this.titleId}-media-caption`; },
    imageSizes() {
      return this.index === 0
        ? '(max-width: 760px) calc(100vw - 40px), (max-width: 1000px) calc((100vw - 108px) / 2), (max-width: 1360px) calc((100vw - 80px) * 0.556), 711px'
        : '(max-width: 760px) calc(100vw - 40px), (max-width: 1360px) calc((100vw - 108px) / 2), 626px';
    },
    images() {
      const media = this.media.length ? this.media : [{ id: 'preview', src: this.portfolio.picture, alt: `${this.portfolio.name} project preview` }];
      return media.map(item => ({ ...item, caption: this.portfolio.mediaCaptions?.[item.id] }));
    },
    selectedMedia() { return this.images[this.selectedIndex]; },
    imageSrcset() {
      const item = this.selectedMedia;
      return item.small ? `${item.small} ${item.smallWidth}w, ${item.src} ${item.width}w` : undefined;
    },
  },
  mounted() {
    this.motionQuery = window.matchMedia('(prefers-reduced-motion: reduce)');
    this.reducedMotion = this.motionQuery.matches;
    this.motionQuery.addEventListener('change', this.onMotionChange);
    document.addEventListener('visibilitychange', this.updateVideo);
    this.observer = new IntersectionObserver(([entry]) => { this.inView = entry.isIntersecting; this.updateVideo(); }, { threshold: .15 });
    this.observer.observe(this.$el);
  },
  beforeUnmount() {
    this.observer.disconnect();
    this.motionQuery.removeEventListener('change', this.onMotionChange);
    document.removeEventListener('visibilitychange', this.updateVideo);
  },
  methods: {
    selectImage(index) {
      this.selectedIndex = index;
      this.autoplayDisabled = false;
      this.$nextTick(this.updateVideo);
    },
    onMotionChange(event) { this.reducedMotion = event.matches; this.updateVideo(); },
    onPause() { if (this.inView && !document.hidden) this.autoplayDisabled = true; },
    updateVideo() {
      const video = this.$refs.video;
      if (!video) return;
      if (this.inView && !this.reducedMotion && !this.autoplayDisabled && !document.hidden) {
        video.muted = true;
        video.play().catch(() => { /* Native controls remain available if autoplay is blocked. */ });
      } else video.pause();
    },
  },
};
</script>

